def _revert(text: str, edits, what: str) -> str:
    for before, after in edits:
        found = text.count(after)
        if found != 1:
            raise AssertionError(f"Dump V2 {what} edit found {found}x (expected exactly once): {after[:70]!r}")
        text = text.replace(after, before)
    return text


def pre_dump_v2_firmware(fw_text: str) -> str:
    """The whole firmware YAML with exactly Dump V2's edits reverted - main @
    004040b byte-for-byte (BASE_FIRMWARE_SHA)."""
    return _revert(fw_text, FIRMWARE_TEXT_EDITS, "firmware")


def pre_dump_v2_boot(boot_lambda: str) -> str:
    """The on_boot lambda with exactly Dump V2's edits reverted."""
    return _revert(boot_lambda, ON_BOOT_EDITS, "on_boot")


def pre_dump_v2_header(header: str) -> str:
    """The durable header with exactly Dump V2's edits reverted."""
    return _revert(header, HEADER_EDITS, "header")


def pre_dump_v2_script(script_id: str, body: str) -> str:
    """A script body with exactly Dump V2's edits to it reverted (unchanged
    for every script Dump V2 did not edit)."""
    return _revert(body, SCRIPT_EDITS.get(script_id, []), f"script {script_id}")


def pre_dump_v2_globals(globals_list: list) -> list:
    """The parsed globals list with exactly Dump V2's added globals removed."""
    present = [g["id"] for g in globals_list if g["id"] in ADDED_GLOBALS]
    if sorted(present) != sorted(ADDED_GLOBALS):
        raise AssertionError(f"Dump V2 globals: expected {ADDED_GLOBALS}, found {present}")
    return [g for g in globals_list if g["id"] not in ADDED_GLOBALS]


def sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()
